    -- ────────────────────────────────────────────────────────────────────────
    ('MLI', 'digital_infrastructure', 'Digital Infrastructure',
      $$Mali's digital infrastructure is developing through mobile network expansion, fiber backbone investment, landlocked connectivity, and digital services growth in a challenging security context.$$,
      $$Mali is expanding telecommunications infrastructure including mobile networks, fiber backbone connecting major cities, and international connectivity via neighboring coastal countries. E-government services and digital identity programs are developing. Landlocked geography requires transit arrangements for bandwidth. Security challenges in northern and central regions affect infrastructure deployment. ICT sector development targets digital services and youth employment. The sector represents opportunity for connectivity expansion, mobile services growth, digital public infrastructure, and technology adoption supporting economic development, government services, and youth employment in a landlocked, security-challenged Sahel context with growing digital demand and demographic youth population.$$,
      48, 65, 1, 'explorer'),
    ('MLI', 'fintech_digital_finance', 'Fintech and Digital Finance',
      $$Mali's financial sector features mobile money dominance, banking infrastructure, WAEMU integration, gold sector financial services, and remittance flows serving financial inclusion.$$,
      $$Mali's financial sector is characterized by substantial mobile money adoption supporting payments, remittances, and financial inclusion across widespread geography. West African Economic and Monetary Union membership provides monetary stability. Banking infrastructure serves urban centers, particularly Bamako. Microfinance institutions provide rural credit access. Gold sector creates financial services demand. Remittances from Malian diaspora support household incomes. The sector is positioned for mobile financial services expansion, digital remittance platforms, payment infrastructure, and financial inclusion initiatives serving gold mining economy, agricultural population, informal sector, landlocked trade, and youth demographic with strong mobile money foundation and diaspora connections in a challenging security environment.$$,
      55, 68, 2, 'explorer'),
    ('MLI', 'energy_renewables', 'Energy and Renewables',
      $$Mali's energy sector combines hydropower generation, solar energy potential, biomass resources, regional power imports, and electrification challenges in Sahel context.$$,
      $$Mali generates hydropower and imports electricity from regional neighbors while facing electrification challenges, particularly in rural areas. The country possesses substantial solar energy potential given Sahel climate and is expanding solar deployment. Biomass remains primary energy source for many households. Regional power integration via West African Power Pool supports energy access. Security challenges affect infrastructure in northern regions. The sector represents opportunity for solar energy development, mini-grid deployment, hydropower expansion, and energy access programs supporting economic development, poverty reduction, and agricultural productivity in a landlocked, Sahel, security-challenged environment with solar resources and growing energy demand.$$,
      48, 70, 3, 'explorer'),
    ('MLI', 'agriculture_agribusiness', 'Agriculture and Agribusiness',
      $$Mali's agriculture includes cotton, rice, millet, sorghum, livestock, and Niger River irrigation supporting livelihoods and food security in Sahel conditions.$$,
      $$Mali's agricultural sector produces cotton (major export), cereals including rice, millet, and sorghum, livestock, and food crops. The country benefits from Niger River irrigation potential in Office du Niger and delta regions. Agriculture supports majority of population and livelihoods. Sahel climate creates vulnerability to drought and climate variability. Government programs support irrigation investment, climate-resilient farming, and value chain development. Livestock sector is significant. The sector represents opportunity for irrigation agriculture expansion, agro-processing investment, cotton sector upgrading, livestock value chains, and climate-smart agriculture serving export markets and food security in a landlocked, Sahel agricultural economy with irrigation potential and pastoral traditions.$$,
      58, 65, 4, 'explorer'),
    ('MLI', 'mining_critical_minerals', 'Mining and Critical Minerals',
      $$Mali's mining sector is anchored by gold production, with industrial and artisanal mining driving exports, alongside exploration for lithium and other minerals.$$,
      $$Mali is a major African gold producer with industrial mining operations and substantial artisanal and small-scale mining activity. Gold exports are the primary export revenue source and foreign exchange earner. The country's geology supports exploration for lithium, copper, and other minerals. Mining sector operates in challenging security context affecting northern region access. Governance reforms address artisanal sector formalization and transparency. The sector represents significant opportunity for gold mining expansion, lithium exploration, artisanal sector support, and resource governance supporting economic growth, government revenues, and rural employment in a gold-dependent economy with emerging critical mineral potential operating in security-challenged regions.$$,
      65, 70, 5, 'explorer'),
    ('MLI', 'logistics_trade', 'Logistics and Trade',
      $$Mali's logistics infrastructure includes landlocked river and road corridors via Senegal and Côte d'Ivoire, Niger River transport, and regional trade positioning.$$,
      $$Mali is landlocked, relying on transit corridors through Senegal (Dakar) and Côte d'Ivoire (Abidjan) for seaport access. Road networks connect to coastal ports and regional markets. Niger River supports inland water transport. Rail connection to Dakar serves freight. Economic Community of West African States integration supports regional trade. Security challenges affect northern transit routes. Cotton and gold exports drive logistics demand. The sector represents opportunity for transport corridor investment, border trade facilitation, river transport services, and regional connectivity infrastructure supporting landlocked trade competitiveness, mining and agricultural exports, and regional commerce in a security-challenged, landlocked Sahel context with river transport potential.$$,
      50, 62, 6, 'explorer'),
    ('MLI', 'tourism_hospitality', 'Tourism and Hospitality',
      $$Mali's tourism potential includes Timbuktu heritage, Dogon Country, Niger River, and Saharan routes constrained by security challenges affecting destination development.$$,
      $$Mali possesses extraordinary tourism potential including UNESCO World Heritage sites at Timbuktu and Djenné, Dogon Country cliffs and culture, Niger River, and Saharan landscapes. Tourism sector has been severely constrained by security challenges and conflict in northern and central regions. Hospitality infrastructure exists in Bamako and previously in tourist zones. Cultural and heritage tourism represents significant potential unrealized due to security conditions. The sector represents very long-term opportunity for heritage tourism recovery, Saharan tourism, cultural tourism development, and destination rehabilitation contingent on security stabilization, peace consolidation, and visitor confidence restoration enabling access to world-class cultural heritage and Saharan assets.$$,
      35, 50, 7, 'explorer'),

    -- ────────────────────────────────────────────────────────────────────────
    -- MAURITANIA (MRT) — All 7 Sectors
    -- ────────────────────────────────────────────────────────────────────────
    ('MRT', 'digital_infrastructure', 'Digital Infrastructure',
      $$Mauritania's digital infrastructure combines mobile network coverage, fiber backbone expansion, Atlantic submarine cable connectivity, and digital services supporting Saharan geography.$$,
      $$Mauritania is expanding telecommunications infrastructure including mobile networks covering urban centers and coastal regions, fiber backbone networks, and Atlantic submarine cable connectivity providing international bandwidth. E-government services and digital identity programs support administrative modernization. Saharan geography creates connectivity challenges for dispersed population. ICT sector development targets digital services. The sector represents opportunity for connectivity expansion across desert geography, mobile services growth, digital public infrastructure, satellite connectivity for remote areas, and technology adoption supporting economic development, government efficiency, mining sector operations, and fisheries management in a Saharan, Atlantic-facing country with dispersed population and resource economy.$$,
      52, 68, 1, 'explorer'),
    ('MRT', 'fintech_digital_finance', 'Fintech and Digital Finance',
      $$Mauritania's financial sector features Islamic banking, mobile money growth, conventional banking, remittance services, and financial inclusion addressing access challenges.$$,
      $$Mauritania's financial sector combines Islamic and conventional banking with expanding mobile money adoption supporting financial inclusion. The country's dual banking system serves diverse preferences. Remittances from Mauritanian diaspora contribute to household incomes. Banking infrastructure serves urban centers, particularly Nouakchott. Mobile money addresses geographic dispersion and financial access gaps. Microfinance institutions provide credit access. The sector is positioned for mobile financial services expansion, Islamic fintech solutions, digital remittance platforms, and financial inclusion initiatives serving fishing economy, mining sector, agricultural and pastoral populations, and diaspora connections in a Saharan geography with Islamic finance preferences and mobile money growth potential.$$,
      50, 68, 2, 'explorer'),
    ('MRT', 'energy_renewables', 'Energy and Renewables',
      $$Mauritania's energy sector combines gas resources, solar and wind potential, renewable energy expansion, and regional power integration addressing energy access challenges.$$,
      $$Mauritania produces natural gas for domestic power generation and potential regional export. The country possesses exceptional solar and wind energy potential in Saharan and Atlantic coastal regions. Renewable energy projects are under development targeting domestic supply and potential regional export. Energy access rates are improving but remain incomplete, particularly in rural areas. Regional power integration with Senegal and West African Power Pool supports energy trade. The sector represents strategic opportunity for solar and wind energy development, gas-to-power projects, renewable energy export potential, and energy access programs supporting mining industrialization, economic development, and positioning as renewable energy supplier leveraging Saharan solar and Atlantic wind resources.$$,
      55, 75, 3, 'explorer'),
    ('MRT', 'agriculture_agribusiness', 'Agriculture and Agribusiness',
      $$Mauritania's agriculture includes dates, livestock, irrigated agriculture along Senegal River, fisheries, and food security initiatives in Saharan environment.$$,
      $$Mauritania's agricultural sector includes livestock (traditional pastoral economy), dates in oases, and irrigated agriculture along Senegal River valley. The country faces Saharan climate constraints limiting cultivation. Fisheries represent primary renewable natural resource with rich Atlantic waters supporting industrial and artisanal fishing. Agriculture and livestock support rural livelihoods. Irrigation development targets food security. The sector represents opportunity for irrigated agriculture expansion, livestock value chains, date production, fisheries sector development including processing and value addition, and aquaculture serving export markets and food security in a Saharan, pastoral, and maritime economy with significant fisheries resources.$$,
      52, 62, 4, 'explorer'),
    ('MRT', 'mining_critical_minerals', 'Mining and Critical Minerals',
      $$Mauritania's mining sector includes iron ore, gold, copper, and exploration for critical minerals supporting export revenues and industrial development.$$,
      $$Mauritania is a significant iron ore producer with established mining operations and rail infrastructure connecting mines to Atlantic port. The country also produces gold and copper. Geological potential exists for additional mineral resources. Mining sector contributes substantially to export revenues and GDP. Trans-Saharan rail corridors support mineral transport. Government mining sector frameworks support investment attraction and revenue management. The sector represents opportunity for iron ore sector expansion, gold and copper mining development, mineral exploration, resource beneficiation, and mining infrastructure investment supporting export earnings, economic development, and infrastructure connectivity in a mineral-rich, Saharan economy.$$,
      62, 68, 5, 'explorer'),
    ('MRT', 'logistics_trade', 'Logistics and Trade',
      $$Mauritania's logistics infrastructure includes Atlantic ports, mining rail corridors, road networks, Saharan routes, and positioning for Sahel-Atlantic trade connectivity.$$,
      $$Mauritania operates Atlantic port facilities at Nouakchott and Nouadhibou serving imports, iron ore and fish exports, and regional trade. Mining rail infrastructure connects iron ore deposits to port. Road networks connect urban centers and border crossings with Senegal, Mali, and Morocco. Trans-Saharan routes link Mauritania to West and North Africa. Fishing sector drives port activity. The country participates in regional trade integration. The sector represents opportunity for port expansion, fishing infrastructure, mining rail investment, road corridor development, and trans-Saharan connectivity positioning Mauritania as Sahel-Atlantic gateway serving resource exports, regional trade, and trans-Saharan commerce leveraging Atlantic access and mineral transport infrastructure.$$,
      58, 68, 6, 'explorer'),
    ('MRT', 'tourism_hospitality', 'Tourism and Hospitality',
      $$Mauritania's tourism potential includes Saharan landscapes, Banc d'Arguin marine park, Chinguetti heritage, and adventure tourism addressing access and infrastructure challenges.$$,
      $$Mauritania offers unique tourism assets including Banc d'Arguin National Park (UNESCO World Heritage) with coastal wetlands and birdlife, Saharan dunes and landscapes, ancient trading cities including Chinguetti, and nomadic culture. Tourism sector is limited by infrastructure, access challenges, and security considerations in some regions. Hospitality infrastructure is minimal beyond Nouakchott. Specialized adventure tourism and birding tourism represent niches. The sector represents long-term opportunity for eco-tourism development, Saharan desert tourism, cultural heritage tourism, marine park tourism, and adventure travel serving specialized international tourism niches as infrastructure develops and destination awareness increases.$$,
      40, 58, 7, 'explorer'),

    -- ────────────────────────────────────────────────────────────────────────
    -- NIGER (NER) — All 7 Sectors
    -- ────────────────────────────────────────────────────────────────────────
    ('NER', 'digital_infrastructure', 'Digital Infrastructure',
      $$Niger's digital infrastructure is developing through mobile network expansion, fiber backbone investment, landlocked connectivity via trans-Saharan cables, and digital services growth.$$,
      $$Niger is expanding telecommunications infrastructure including mobile networks, fiber backbone connecting major cities, and international connectivity via trans-Saharan fiber cables through Algeria and coastal country transit. E-government services and digital identity programs support development. Landlocked Sahel geography creates connectivity challenges. Security conditions in some regions affect infrastructure deployment. ICT sector development targets digital services and youth employment. The sector represents opportunity for connectivity expansion, mobile services growth, trans-Saharan digital corridor participation, digital public infrastructure, and technology adoption supporting economic development, government efficiency, and youth employment in a landlocked, Sahel context with trans-Saharan connectivity potential.$$,
      45, 68, 1, 'explorer'),
    ('NER', 'fintech_digital_finance', 'Fintech and Digital Finance',
      $$Niger's financial sector features mobile money expansion, banking infrastructure, WAEMU integration, uranium sector finance, and financial inclusion serving unbanked Sahel populations.$$,
      $$Niger's financial sector is characterized by growing mobile money adoption supporting payments and financial inclusion given limited banking reach in dispersed Sahel geography. West African Economic and Monetary Union membership provides monetary stability. Banking infrastructure serves urban centers, particularly Niamey. Microfinance institutions reach rural areas. Uranium mining sector creates financial services demand. Remittances from Nigerian diaspora support incomes. The sector is positioned for mobile financial services expansion, digital remittance platforms, payment infrastructure, and financial inclusion initiatives serving mining economy, agricultural and pastoral populations, informal sector, and landlocked trade in a Sahel context with substantial mobile money potential and diaspora connections.$$,
      48, 70, 2, 'explorer'),
    ('NER', 'energy_renewables', 'Energy and Renewables',
      $$Niger's energy sector combines uranium resources, solar energy potential, low electrification rates, and mini-grid programs addressing severe energy access challenges.$$,
      $$Niger possesses uranium resources while facing severe energy access challenges with very low electrification rates among Africa's lowest. The country has exceptional solar energy potential given Saharan and Sahel climate. Solar deployment through mini-grids and off-grid systems is expanding. Regional power imports supplement minimal domestic generation. Energy access is a critical development constraint. Uranium sector requires reliable power supply. The sector represents substantial opportunity for solar energy development, mini-grid deployment, off-grid electrification, and energy access programs supporting uranium mining operations, agricultural productivity, economic development, and poverty reduction in a Sahel, energy-deficient, landlocked country with abundant solar resources and uranium wealth paradox.$$,
      35, 75, 3, 'explorer'),
    ('NER', 'agriculture_agribusiness', 'Agriculture and Agribusiness',
      $$Niger's agriculture includes millet, sorghum, livestock, cowpeas, onions, and food security initiatives in Sahel environment facing climate vulnerability.$$,
      $$Niger's agricultural sector produces millet, sorghum, cowpeas, onions, and livestock in Sahel conditions with substantial climate vulnerability and food security challenges. Agriculture and livestock support majority of livelihoods. The country faces recurrent droughts, land degradation, and water scarcity. Government and development programs support climate-resilient agriculture, irrigation, agroforestry, and food security. Livestock sector is significant with pastoral traditions. Niger River valley offers irrigation potential. The sector represents opportunity for climate-smart agriculture, irrigation development, livestock value chains, agroforestry, food security programs, and agricultural resilience serving rural livelihoods and food security in a Sahel, drought-prone, food-insecure context with irrigation potential and pastoral economy.$$,
      50, 62, 4, 'explorer'),
    ('NER', 'mining_critical_minerals', 'Mining and Critical Minerals',
      $$Niger's mining sector is anchored by uranium production, with gold, coal, and exploration for critical minerals including lithium supporting economic diversification.$$,
      $$Niger is a significant uranium producer supplying international markets, with uranium representing major export revenue source. The country also produces gold and coal. Geological potential supports exploration for lithium, rare earths, and other minerals. Mining sector operates in challenging Sahel security context. Oil production is at early stages. Government mining sector frameworks support investment while addressing revenue transparency and local content. The sector represents opportunity for uranium sector sustainability, gold mining expansion, lithium and critical mineral exploration, resource diversification, and mining governance supporting economic development, government revenues, and employment in a uranium-dependent economy with emerging diversification potential and security challenges.$$,
      58, 70, 5, 'explorer'),
    ('NER', 'logistics_trade', 'Logistics and Trade',
      $$Niger's logistics infrastructure includes landlocked corridors via Benin and Nigeria, road networks, trans-Saharan routes, and positioning for Sahel-coastal connectivity.$$,
      $$Niger is landlocked, relying on transit corridors through Benin (Cotonou) and Nigeria (Lagos) for seaport access, with road networks connecting to coastal ports. Trans-Saharan routes link Niger to Algeria and Libya. The country serves as transit corridor between coastal West Africa and North Africa and Libya. Uranium exports drive specialized logistics. Economic Community of West African States integration supports regional trade. Security challenges affect some corridors. The sector represents opportunity for transport corridor investment, border trade facilitation, trans-Saharan route development, and regional logistics hub positioning serving landlocked trade, uranium exports, agricultural exports, and trans-Saharan commerce in a challenging Sahel, landlocked, security-affected context with strategic corridor positioning.$$,
      45, 65, 6, 'explorer'),
    ('NER', 'tourism_hospitality', 'Tourism and Hospitality',
      $$Niger's tourism potential includes Saharan landscapes, Air Mountains, wildlife reserves, Nigerien culture, and destination development constrained by security challenges.$$,
      $$Niger offers unique tourism potential including Saharan landscapes, Air and Ténéré Natural Reserves (UNESCO World Heritage) with desert, mountains, and wildlife including addax, 'W' National Park with elephants and lions, and Nigerien culture. Tourism sector has been severely constrained by security challenges particularly in Saharan regions. Hospitality infrastructure is limited beyond Niamey. Cultural festivals and desert tourism represented potential prior to security deterioration. The sector represents very long-term opportunity for Saharan tourism recovery, wildlife tourism, cultural tourism, and adventure travel serving specialized niches contingent on security stabilization, peace consolidation, and visitor access restoration enabling engagement with extraordinary desert and wildlife assets.$$,
      32, 52, 7, 'explorer'),

    -- ────────────────────────────────────────────────────────────────────────
    -- SIERRA LEONE (SLE) — All 7 Sectors
    -- ────────────────────────────────────────────────────────────────────────
    ('SLE', 'digital_infrastructure', 'Digital Infrastructure',
      $$Sierra Leone's digital infrastructure is rebuilding through mobile network expansion, submarine cable connectivity, e-government services, and digital inclusion programs post-conflict.$$,
      $$Sierra Leone is expanding telecommunications infrastructure including mobile networks, fiber backbone connecting districts, and submarine cable access via ACE cable system. E-government services and digital identity programs support post-conflict state-building and service delivery. ICT sector development targets digital services and youth employment. Free wi-fi initiatives in Freetown support digital access. Digital skills programs address capacity gaps. The sector represents opportunity for connectivity expansion, mobile services growth, digital public infrastructure, youth technology employment, and digital inclusion supporting economic reconstruction, government effectiveness, and youth employment in a post-conflict, post-Ebola recovery context rebuilding digital infrastructure and skills.$$,
      52, 72, 1, 'explorer'),
    ('SLE', 'fintech_digital_finance', 'Fintech and Digital Finance',
      $$Sierra Leone's financial sector features mobile money growth, banking reconstruction, remittance services, microfinance, and financial inclusion addressing post-conflict financial access.$$,
      $$Sierra Leone's financial sector is characterized by substantial mobile money adoption supporting financial inclusion in post-conflict recovery context. Remittances from Sierra Leonean diaspora are significant. Banking infrastructure serves Freetown and provincial centers, rebuilding from conflict and Ebola disruption. Microfinance institutions provide credit access. Central Bank supports digital financial services and payment system modernization. The sector is positioned for mobile banking expansion, digital remittance platforms, payment infrastructure investment, and financial inclusion initiatives serving remittance flows, mining sector, agricultural population, and youth demographic with strong mobile money foundation and diaspora connections in a post-conflict financial reconstruction and Ebola recovery context.$$,
      50, 72, 2, 'explorer'),
    ('SLE', 'energy_renewables', 'Energy and Renewables',
      $$Sierra Leone's energy sector combines hydropower potential, solar deployment, low access rates, post-conflict grid reconstruction, and electrification addressing energy poverty.$$,
      $$Sierra Leone possesses hydropower potential and is rehabilitating generation capacity following conflict damage and underinvestment. The country faces low electrification rates and reliability challenges. Solar energy deployment supports off-grid and mini-grid solutions. Freetown and regional centers receive grid power with frequent outages. Energy sector reconstruction attracts international development support and private investment. Bumbuna hydropower plant supplies significant generation. The sector represents opportunity for hydropower expansion, solar energy development, mini-grid deployment, grid rehabilitation, and energy access programs supporting economic reconstruction, poverty reduction, and mining sector operations in a post-conflict, energy-deficient country with water resources and solar potential.$$,
      45, 75, 3, 'explorer'),
    ('SLE', 'agriculture_agribusiness', 'Agriculture and Agribusiness',
      $$Sierra Leone's agriculture includes rice, palm oil, cocoa, coffee, cashews, and substantial arable land supporting livelihoods and post-conflict revitalization.$$,
      $$Sierra Leone's agricultural sector produces rice, palm oil, cocoa, coffee, cashews, and vegetables. The country possesses substantial arable land, rainfall, and water resources supporting agricultural potential. Agriculture employs majority of population. Post-conflict and post-Ebola recovery includes agricultural sector revitalization. Government programs support smallholder commercialization, value chain development, and food security. Export crops including cocoa and cashews offer revenue potential. The sector represents substantial opportunity for agricultural investment, agro-processing, plantation agriculture recovery, smallholder commercialization, and value chains serving export markets and food security in a post-conflict country with significant agricultural resource endowment, rainfall, and recovery momentum.$$,
      55, 70, 4, 'explorer'),
    ('SLE', 'mining_critical_minerals', 'Mining and Critical Minerals',
      $$Sierra Leone's mining sector includes diamonds, iron ore, rutile, bauxite, and gold supporting economic recovery and governance reforms post-conflict.$$,
      $$Sierra Leone produces diamonds, iron ore (operations resuming), rutile, bauxite, and gold. Mining sector is crucial for economic recovery and export revenues. Diamond sector underwent governance reforms including Kimberley Process certification addressing conflict diamond legacy. Iron ore mining operations are resuming after suspension. Artisanal diamond and gold mining support livelihoods. Post-conflict mining sector transparency and governance reforms represent priorities. The sector represents opportunity for responsible mining investment, diamond sector transparency, iron ore sector revival, artisanal mining formalization, and resource governance supporting economic growth, government revenues, and rural employment in a post-conflict recovery context strengthening extractive sector governance.$$,
      55, 72, 5, 'explorer'),
    ('SLE', 'logistics_trade', 'Logistics and Trade',
      $$Sierra Leone's logistics infrastructure includes Freetown Port, road networks, ECOWAS integration, and post-conflict transport sector reconstruction supporting trade recovery.$$,
      $$Sierra Leone's Port of Freetown is a natural deepwater harbor serving imports, mineral exports, and regional trade potential. Road networks connect districts and border crossings with Guinea and Liberia, with post-conflict rehabilitation ongoing. Economic Community of West African States integration and African Continental Free Trade Area participation support regional trade. Mining sector drives logistics demand for iron ore and mineral exports. The sector represents opportunity for port expansion and modernization, road corridor rehabilitation, border trade facilitation, and regional logistics services leveraging natural harbor, mineral export corridors, and regional connectivity positioning in a post-conflict infrastructure reconstruction and trade recovery context.$$,
      52, 70, 6, 'explorer'),
    ('SLE', 'tourism_hospitality', 'Tourism and Hospitality',
      $$Sierra Leone's tourism potential includes beaches, wildlife reserves, Bunce Island heritage, and destination development addressing post-conflict recovery and infrastructure.$$,
      $$Sierra Leone offers tourism potential including beautiful Atlantic beaches near Freetown, tropical rainforests, Outamba-Kilimi National Park with wildlife including chimpanzees, Bunce Island slave trade heritage, and Creole culture. Tourism sector is in recovery stages following conflict and Ebola outbreak. Hospitality infrastructure exists in Freetown and beach areas. Diaspora and business travel provide baseline activity. Government tourism sector initiatives support destination development and eco-tourism potential. The sector represents opportunity for beach tourism development, eco-tourism, heritage tourism, wildlife tourism, and destination marketing serving regional markets and diaspora visitors as post-conflict and post-Ebola recovery advances and destination awareness grows.$$,
      48, 65, 7, 'explorer'),

    -- ────────────────────────────────────────────────────────────────────────
    -- TOGO (TGO) — All 7 Sectors
    -- ────────────────────────────────────────────────────────────────────────
    ('TGO', 'digital_infrastructure', 'Digital Infrastructure',
      $$Togo's digital infrastructure combines competitive telecommunications, fiber networks, digital public services, innovation programs, and positioning as West African digital hub.$$,
      $$Togo maintains competitive telecommunications infrastructure including mobile networks, fiber backbone, submarine cable connectivity, and free public wi-fi in Lomé. Government Digital Togo programs emphasize e-services, digital identity, and digital economy development. The country positions as a digital innovation hub with startup ecosystem support. E-government platforms are relatively advanced. Regional connectivity supports digital services exports. The sector represents opportunity for digital services expansion, technology startup ecosystem, ICT exports, data center infrastructure, and regional digital hub development leveraging government digitalization drive, small country agility, and regional connectivity serving West African digital economy and government modernization as reference case.$$,
      65, 72, 1, 'explorer'),
    ('TGO', 'fintech_digital_finance', 'Fintech and Digital Finance',
      $$Togo's financial sector features mobile money leadership, banking infrastructure, WAEMU integration, digital payment expansion, and financial inclusion serving regional fintech potential.$$,
      $$Togo's financial sector combines banking infrastructure, strong mobile money adoption, and expanding digital payment ecosystem. West African Economic and Monetary Union membership provides monetary stability. Lomé serves as regional financial center. Mobile money regulation and interoperability are relatively advanced. Banking sector serves urban and expanding to rural areas. Microfinance institutions support financial inclusion. Government digital initiatives include digital payment platforms. The sector represents opportunity for fintech innovation, mobile banking services, regional payment hub development, digital financial services exports, and financial inclusion initiatives leveraging mobile money leadership, regulatory environment, and government digital programs serving domestic market and regional West African fintech ecosystem.$$,
      65, 70, 2, 'explorer'),
    ('TGO', 'energy_renewables', 'Energy and Renewables',
      $$Togo's energy sector combines imported power, solar deployment, regional power integration, and electrification programs supporting industrialization and services economy.$$,
      $$Togo imports electricity from Ghana and regional sources while developing domestic generation including solar energy. The country participates in West African Power Pool for regional power trade. Solar energy deployment is expanding through utility-scale and distributed systems. Energy access rates are improving with government electrification programs. Port and logistics sector drives power demand. The sector represents opportunity for solar energy investment, domestic generation capacity expansion, energy storage, regional power trade, and energy access programs supporting port operations, industrial development, digital economy infrastructure, and economic growth in a small, trade-oriented economy with regional power integration and solar potential.$$,
      55, 70, 3, 'explorer'),
    ('TGO', 'agriculture_agribusiness', 'Agriculture and Agribusiness',
      $$Togo's agriculture includes coffee, cocoa, cotton, palm oil, and food crops supporting export revenues, rural livelihoods, and agro-processing development.$$,
      $$Togo's agricultural sector produces coffee, cocoa, cotton, palm oil, cashews, and food crops including cassava and maize. Agriculture supports significant rural employment and export revenues. Government programs support agricultural modernization, organic farming, and value chain development. Phosphate-based fertilizer production supports agriculture. Port of Lomé facilitates agricultural exports and regional transit trade. The sector represents opportunity for agro-processing investment, organic agriculture, value-added products, agricultural finance, and export agriculture development serving regional and international markets leveraging port access, diverse production, and regional trade positioning in a small, export-oriented agricultural economy.$$,
      60, 68, 4, 'explorer'),
    ('TGO', 'mining_critical_minerals', 'Mining and Critical Minerals',
      $$Togo's mining sector includes phosphates, clinker, limestone, and exploration for mineral resources supporting export revenues and industrial inputs.$$,
      $$Togo produces phosphates for export and domestic fertilizer production, alongside clinker, limestone, and other industrial minerals. Phosphate sector is undergoing modernization and investment. Geological potential exists for additional mineral exploration. Mining sector contributes to export revenues and industrial supply. Government mining sector reforms support investment attraction and governance. The sector represents opportunity for phosphate sector expansion and modernization, mineral exploration, limestone and clinker production, and industrial minerals development supporting export revenues, agricultural inputs through fertilizer production, and construction materials in a small economy with phosphate resources and industrial mineral potential.$$,
      55, 62, 5, 'explorer'),
    ('TGO', 'logistics_trade', 'Logistics and Trade',
      $$Togo's logistics infrastructure is anchored by Lomé Port serving landlocked neighbors, free zones, road corridors, ECOWAS integration, and positioning as West African logistics hub.$$,
      $$Togo's Port of Lomé is a major West African port serving imports, exports, and substantial transit trade for landlocked Burkina Faso, Niger, and Mali. The country operates Africa's deepest port with container terminal and efficient operations. Free zones support trade and light manufacturing. Road corridors connect port to hinterland markets. Economic Community of West African States integration and African Continental Free Trade Area participation support regional trade positioning. Government port and corridor modernization drives competitiveness. The sector represents substantial opportunity for port expansion, logistics services, corridor infrastructure, free zone development, and regional distribution hub positioning leveraging efficient port operations, landlocked neighbor transit, and strategic West African logistics gateway role.$$,
      70, 72, 6, 'explorer'),
    ('TGO', 'tourism_hospitality', 'Tourism and Hospitality',
      $$Togo's tourism economy features coastal beaches, voodoo cultural heritage, Koutammakou landscapes, wildlife reserves, and destination development serving regional and cultural tourism.$$,
      $$Togo offers tourism assets including Atlantic coastal beaches, voodoo cultural heritage and festivals, UNESCO World Heritage Koutammakou landscape with traditional Batammariba architecture, Fazao-Malfakassa National Park, and diverse cultural traditions. The country positions as cultural and beach tourism destination. Hospitality infrastructure exists in Lomé and coastal areas. Regional and diaspora tourism support baseline visitors. Government tourism sector initiatives emphasize destination development, cultural heritage, and eco-tourism. The sector represents opportunity for beach resort investment, cultural tourism development, heritage tourism, eco-tourism, and hospitality infrastructure serving West African regional tourism, cultural heritage travelers, and diaspora visitors leveraging coastal access and unique cultural assets.$$,
      58, 68, 7, 'explorer')

  ) AS v(iso3, sector_key, sector_label, teaser_md, rationale_md, strength_score, growth_score, display_order, min_plan_id)
)
INSERT INTO public.souvera_country_sectors (
  country_id, sector_key, sector_label, teaser_md, rationale_md, 
  strength_score, growth_score, display_order, min_plan_id
)
SELECT 
  c.id AS country_id,
  s.sector_key,
  s.sector_label,
  s.teaser_md,
  s.rationale_md,
  s.strength_score,
  s.growth_score,
  s.display_order,
  s.min_plan_id
FROM sector_seed s
JOIN public.souvera_countries c ON c.iso3 = s.iso3
ON CONFLICT (country_id, sector_key) DO UPDATE SET
  sector_label = EXCLUDED.sector_label,
  teaser_md = EXCLUDED.teaser_md,
  rationale_md = EXCLUDED.rationale_md,
  strength_score = EXCLUDED.strength_score,
  growth_score = EXCLUDED.growth_score,
  display_order = EXCLUDED.display_order,
  min_plan_id = EXCLUDED.min_plan_id,
  updated_at = now();
